#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007;
int K;
vector<ll> C; // C[1..K]: a_i = sum_{j=1}^{K} C[j]*a_{i-j}   (characteristic poly Q(x) = x^K - C[1]x^{K-1} - ... - C[K])

vector<ll> polyMul(const vector<ll> &A, const vector<ll> &B) {
    vector<ll> R(A.size() + B.size() - 1, 0);
    for (size_t i = 0; i < A.size(); i++) {
        if (A[i] == 0) continue;
        for (size_t j = 0; j < B.size(); j++) {
            R[i+j] = (R[i+j] + A[i] * B[j]) % MOD;
        }
    }
    return R;
}

// reduce a polynomial (coeff vector, degree possibly >= K) modulo Q(x), result has exactly K coeffs (degree < K)
vector<ll> reduceMod(vector<ll> Pc) {
    for (int d = (int)Pc.size() - 1; d >= K; d--) {
        if (Pc[d] == 0) continue;
        ll coef = Pc[d];
        Pc[d] = 0;
        for (int j = 1; j <= K; j++) {
            Pc[d-j] = (Pc[d-j] + coef * C[j]) % MOD;
        }
    }
    Pc.resize(K);
    return Pc;
}

// compute x^n mod Q(x), returned as a length-K coefficient vector
vector<ll> polyPowX(ll n) {
    vector<ll> result(K, 0);
    result[0] = 1; // polynomial "1"
    vector<ll> base(K, 0);
    if (K == 1) base[0] = C[1] % MOD; // x === C[1] (mod Q) when Q(x) = x - C[1]
    else base[1] = 1;                // polynomial "x"
    while (n > 0) {
        if (n & 1) result = reduceMod(polyMul(result, base));
        base = reduceMod(polyMul(base, base));
        n >>= 1;
    }
    return result;
}

int main(){
    ll n;
    cin >> K >> n;
    C.assign(K+1, 0);
    for (int j = 1; j <= K; j++) cin >> C[j];
    vector<ll> a(K);
    for (int i = 0; i < K; i++) cin >> a[i];

    vector<ll> coef = polyPowX(n); // a_n = sum coef[i]*a_i
    ll ans = 0;
    for (int i = 0; i < K; i++) ans = (ans + coef[i] * (a[i] % MOD)) % MOD;
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const ll MOD = 1000000007;

ll power(ll a, ll e, ll mod) {
    a %= mod; if (a < 0) a += mod;
    ll r = 1;
    while (e > 0) { if (e & 1) r = r * a % mod; a = a * a % mod; e >>= 1; }
    return r;
}
ll modinv(ll a) { return power(a, MOD-2, MOD); }

vector<ll> polyMul(const vector<ll> &A, const vector<ll> &B) {
    if (A.empty() || B.empty()) return {};
    vector<ll> R(A.size() + B.size() - 1, 0);
    for (size_t i = 0; i < A.size(); i++) {
        if (A[i] == 0) continue;
        for (size_t j = 0; j < B.size(); j++) {
            R[i+j] = (R[i+j] + A[i] * B[j]) % MOD;
        }
    }
    return R;
}

// [x^n] P(x)/Q(x) via Bostan-Mori doubling. Q[0] must be 1 (and stays 1 throughout).
ll bostanMori(vector<ll> P, vector<ll> Q, ll n) {
    while (n > 0) {
        // Qneg(x) = Q(-x): negate odd-index coefficients
        vector<ll> Qneg = Q;
        for (size_t i = 1; i < Qneg.size(); i += 2) {
            Qneg[i] = (MOD - Qneg[i]) % MOD;
        }
        vector<ll> numer = polyMul(P, Qneg);
        vector<ll> denom = polyMul(Q, Qneg);
        int parity = n & 1;
        vector<ll> newP, newQ;
        for (size_t i = parity; i < numer.size(); i += 2) newP.push_back(numer[i]);
        for (size_t i = 0; i < denom.size(); i += 2) newQ.push_back(denom[i]);
        if (newP.empty()) newP.push_back(0);
        P = newP; Q = newQ;
        n >>= 1;
    }
    return P[0] % MOD * modinv(Q[0] % MOD) % MOD;
}

int main(){
    int K;
    ll n;
    cin >> K >> n;
    vector<ll> c(K+1, 0); // c[1..K]: a_i = sum c_j * a_{i-j}
    for (int j = 1; j <= K; j++) cin >> c[j];
    vector<ll> a(K);
    for (int i = 0; i < K; i++) cin >> a[i];

    // Q(x) = 1 - c_1 x - c_2 x^2 - ... - c_K x^K
    vector<ll> Q(K+1, 0);
    Q[0] = 1;
    for (int j = 1; j <= K; j++) Q[j] = (MOD - c[j] % MOD) % MOD;

    // P(x) = (A(x) * Q(x)) truncated to degree < K, using only known terms a_0..a_{K-1}
    vector<ll> P(K, 0);
    for (int i = 0; i < K; i++) {
        ll s = 0;
        for (int j = 0; j <= i; j++) {
            s = (s + Q[j] * (a[i-j] % MOD)) % MOD;
        }
        P[i] = s;
    }

    cout << bostanMori(P, Q, n) << endl;
}
